query:
{
  vaults(
    where: { depositor: "0xd51d8dda9f8975fbecacd77a93f37a57053642e1" }
    orderBy: "pendingAt"
    orderDirection: "desc"
    limit: 3
  ) {
    totalCount
    items {
      id
      status
      amount
      inUse
      activatedAt
    }
  }
}

{
  aavePosition(depositorAddress: "0xd51d8dda9f8975fbecacd77a93f37a57053642e1") {
    totalCollateral
    proxyContract
    collaterals(where: { removedAt: null }, limit: 3) {
      totalCount
      items {
        vaultId
        amount
        addedAt
      }
    }
  }
}

{
  vaultActivitys(
    where: { depositor: "0xd51d8dda9f8975fbecacd77a93f37a57053642e1" }
    orderBy: "timestamp"
    orderDirection: "desc"
    limit: 3
  ) {
    items {
      type
      amount
      vaultId
      debtReserveId
      timestamp
    }
  }
}

{
  aaveReserves {
    items {
      id
      borrowable
      underlyingToken {
        symbol
        decimals
      }
    }
  }
}

{
  vaults(
    where: { status_in: [pending, signatures_collected, verified] }
    orderBy: "pendingAt"
    orderDirection: "desc"
    limit: 3
  ) {
    totalCount
    items {
      id
      status
      ackCount
      pendingAt
    }
  }
}

{
  statss(limit: 1) {
    items {
      totalAvailableSats
      availableVaultCount
    }
  }
}

{
  pending: vaults(where: { status: pending }) { totalCount }
  available: vaults(where: { status: available }) { totalCount }
  expired: vaults(where: { status: expired }) { totalCount }
  liquidated: vaults(where: { status: liquidated }) { totalCount }
}

{
  vaultProviderStatss(
    orderBy: "totalActiveSats"
    orderDirection: "desc"
    limit: 4
  ) {
    items {
      activeVaultCount
      totalActiveSats
      provider {
        name
        commissionBps
      }
    }
  }
}

{
  _meta {
    status
  }
}

{
  vaults(
    where: { AND: [{ status: available }, { inUse: true }] }
    orderBy: "amount"
    orderDirection: "desc"
    limit: 3
  ) {
    totalCount
    items {
      id
      amount
      depositor
    }
  }
}

{
  aaveVaultStatus(
    vaultId: "0x822ecce7d8dac56426935b3c344778cb214eec1a368100a190ea2b31d3c56d3f"
  ) {
    status
    vaultId
  }
}

{
  vaults(
    where: { status: expired }
    orderBy: "expiredAt"
    orderDirection: "desc"
    limit: 3
  ) {
    items {
      id
      expiredAt
      expirationReason
      claimExpiredUntil
    }
  }
}

{
  vaultActivitys(
    where: { type: liquidation }
    orderBy: "timestamp"
    orderDirection: "desc"
    limit: 3
  ) {
    totalCount
    items {
      vaultId
      amount
      timestamp
      transactionHash
    }
  }
}

{
  vaults(orderBy: "pendingAt", orderDirection: "asc", limit: 2, offset: 0) {
    totalCount
    pageInfo {
      hasNextPage
      endCursor
    }
    items {
      id
      status
    }
  }
}

{
  vaultActivitys(
    where: { timestamp_gt: "1786000000" }
    orderBy: "timestamp"
    orderDirection: "asc"
    limit: 3
  ) {
    totalCount
    items {
      id
      type
      timestamp
    }
  }
}

{
  vaults(
    where: { depositor: "0x106d71c740aeebf6e72f06dad4129651dc65d810" }
    orderBy: "pendingAt"
    orderDirection: "desc"
    limit: 10
  ) {
    totalCount
    items {
      id
      status
      amount
      activatedAt
      inUse
    }
  }
}

{
  aavePosition(depositorAddress: "0xd51d8dda9f8975fbecacd77a93f37a57053642e1") {
    totalCollateral
    proxyContract
    createdAt
    updatedAt
    collaterals(limit: 10) {
      totalCount
      items {
        vaultId
        amount
        addedAt
        removedAt
        liquidationIndex
      }
    }
  }
}

{
  vaultActivitys(
    where: { depositor: "0x106d71c740aeebf6e72f06dad4129651dc65d810" }
    orderBy: "timestamp"
    orderDirection: "desc"
    limit: 20
  ) {
    totalCount
    items {
      type
      amount
      vaultId
      debtReserveId
      timestamp
      transactionHash
    }
  }
}

{
  statss(limit: 1) {
    items {
      totalAvailableSats
      availableVaultCount
      updatedAt
    }
  }
  protocolStates(limit: 1) {
    items {
      activeVaultCoreVersion
      updatedAt
    }
  }
}

{
  vaultProviders(orderBy: "registeredAt", orderDirection: "asc", limit: 50) {
    totalCount
    items {
      id
      name
      commissionBps
      metadataStatus
      metadataRejectionReason
      registeredAt
    }
  }
}

{
  vaultKeepers(limit: 50) {
    totalCount
    items {
      id
    }
  }
  universalChallengers(limit: 50) {
    totalCount
    items {
      id
    }
  }
  universalChallengerVersions(orderBy: "id", orderDirection: "desc", limit: 5) {
    items {
      id
    }
  }
}

{
  pending: vaults(where: { status: pending }, limit: 1) {
    totalCount
  }
  verified: vaults(where: { status: verified }, limit: 1) {
    totalCount
  }
  available: vaults(where: { status: available }, limit: 1) {
    totalCount
  }
  redeemed: vaults(where: { status: redeemed }, limit: 1) {
    totalCount
  }
  expired: vaults(where: { status: expired }, limit: 1) {
    totalCount
  }
  liquidated: vaults(where: { status: liquidated }, limit: 1) {
    totalCount
  }
}

{
  escrowed: vaultFeeEscrows(where: { status: escrowed }, limit: 1) {
    totalCount
  }
  distributed: vaultFeeEscrows(where: { status: distributed }, limit: 1) {
    totalCount
  }
  refunded: vaultFeeEscrows(where: { status: refunded }, limit: 1) {
    totalCount
  }
  forfeited: vaultFeeEscrows(where: { status: forfeited }, limit: 1) {
    totalCount
  }
}

{
  vaults(orderBy: "pendingAt", orderDirection: "asc", limit: 1000, offset: 0) {
    totalCount
    items {
      id
      status
    }
  }
}

{
  vaults(
    where: {
      AND: [
        { status: available }
        { amount_gte: "1000000" }
        { inUse: true }
      ]
    }
    orderBy: "amount"
    orderDirection: "desc"
    limit: 5
  ) {
    totalCount
    items {
      id
      amount
      inUse
    }
  }
}

{
  vaultFeeEscrows(limit: 3, orderBy: "escrowedAt", orderDirection: "desc") {
    items {
      vaultId
      totalAmount
      status
      numUniversalChallengers
      numAppVaultKeepers
      vault {
        status
        depositor
      }
    }
  }
}

{
  __schema {
    types {
      kind
      name
    }
  }
}

{
  __type(name: "vault") {
    name
    fields {
      name
      type {
        kind
        name
        ofType {
          kind
          name
        }
      }
    }
  }
}

{
  vaults(orderBy: "pendingAt", orderDirection: "asc", limit: 1000, offset: 0) {
    totalCount
    items {
      id
    }
  }
}
